// mixedAssertObservedZeroOnError asserts Observed returns zero alongside any error.
func mixedAssertObservedZeroOnError(
	tb testing.TB,
	m Mixed,
	fx MixedFixture,
) {
	tb.Helper()
	ctx, cancel := context.WithCancel(tb.Context())
	cancel()
	got, err := m.Observed(ctx, fx.Key())
	if err == nil {
		tb.Skip("Observed answered for a cancelled context, so this check has no error to inspect")
	}

	var zero int
	if got != zero {
		tb.Errorf("Observed must return the zero value alongside an error: got %+v, want %+v (err %v)",
			got, zero, err)
	}
}

// mixedAssertTouchSideeffect asserts Touch changes what Observed observes.
func mixedAssertTouchSideeffect(
	tb testing.TB,
	m Mixed,
	fx MixedFixture,
) {
	tb.Helper()
	ctx := tb.Context()

	before, beforeErr := m.Observed(ctx, fx.Key())
	if beforeErr != nil {
		tb.Fatalf("Observed must be readable before Touch runs: %v", beforeErr)
	}

	if err := m.Touch(ctx, fx.Key()); err != nil {
		tb.Fatalf("Touch must succeed before the two readings mean anything: %v", err)
	}

	after, afterErr := m.Observed(ctx, fx.Key())
	if afterErr != nil {
		tb.Fatalf("Observed must still be readable after Touch runs: %v", afterErr)
	}

	if after == before {
		tb.Errorf("Touch must change what Observed observes: both read %+v", before)
	}
}

// mixedAssertObservedMiss asserts Observed reports zero for a key nothing has written.
func mixedAssertObservedMiss(
	tb testing.TB,
	m Mixed,
	fx MixedFixture,
) {
	tb.Helper()
	ctx := tb.Context()

	got, err := m.Observed(ctx, fx.KeyOther())

	var zero int
	if got != zero {
		tb.Errorf("Observed must return the zero value for an input nothing supplied: got %+v, want %+v (err %v)",
			got, zero, err)
	}
}

